---@param packet PidPacket
function PacketSender:sendPidPacket(rakssid, packet, ignoreReady)
    packet.pid = Name2HashId[packet.pid] or packet.pid
    local success, res = pcall(serialize.encode, packet)
    if not success then
        LogUtil.logScriptException("[PacketSender:sendPidPacket]", res)
        return
    end
    PacketSender:sendServerCommonData(rakssid, "Lua", "pid", res, ignoreReady)
end

---@param packet PidPacket
function PacketSender:broadCastPidPacket(packet, ignoreReady)
    packet.pid = Name2HashId[packet.pid] or packet.pid
    local success, res = pcall(serialize.encode, packet)
    if not success then
        LogUtil.logScriptException("[PacketSender:broadCastPidPacket]", res)
        return
    end
    PacketSender:broadCastServerCommonData("Lua", "pid", res, ignoreReady)
end

function PacketSender:sendPidPacketToTracking(entityId, packet, ignoreReady)
    packet.pid = Name2HashId[packet.pid] or packet.pid
    local success, res = pcall(serialize.encode, packet)
    if not success then
        LogUtil.logScriptException("[PacketSender:sendPidPacketToTracking]", res)
        return
    end
    PacketSender:sendLuaCommonDataToTrackingPlayers(entityId, "pid", res, ignoreReady)
end

function PacketSender:syncEntityPlayerInfo(userId, key, value, rakssid)
    local data = DataBuilder.new()
                            :addParam("userId", userId)
                            :addParam(key, value)
                            :getData()
    if rakssid then
        PacketSender:sendServerCommonData(rakssid, "SyncEntityPlayerInfo", "", data)
    else
        PacketSender:broadCastServerCommonData("SyncEntityPlayerInfo", "", data)
    end
end

